from collections import defaultdict

def lcp(s, i, j):
    return len(s[:i+1]) - len(s[j::i+1])

def parse_query(i, q):
    k, l = map(int, q.split())
    a = [-1] + list(map(int, q.split()[1:k+1]))
    b = [_ for _ in q.split()[k+1].split()[1:l+1]]
    return i, k, l, a, b

def calculate_lcp(s, k, l, a, b):
    ans = 0
    for i in a:
        for j in b:
            index_a = a.index(i)
            index_b = b.index(j)
            common_parts = k[i][j] = (k[index_a][index_b] +
                                       len(s[:index_a + 1]) -
                                       len(s[index_b::index_a + 1]))
            ans += common_parts - max(0, common_parts)
    return ans

def solution(n, q, s):
    kpi_ws = []
    kpi = []
    for i in range(q):
        query = parse_query(i, s)
        kpi.append((query[k-1], query[k+1]-1, query[l-1]))
        kpi_ws.append([query[i+1] for i in range(k-1)])
        a, b = query[2:{k-1}-1]
        kpi_ws[i].append((a,b))
        for i in range(len(a)):
            for j in range(len(b)):
                kpi[i].append((a[i], b[j]))
    segtree = DefaultSeuqenceTreeFromPos(kpi, kpi_ws, n)
    ans_queries = defaultdict(int)
    for i, (ri, _, _, _, _, k_star_v, rmi_ws) in enumerate(kpi):
        s = 2 * ri + k_star_v
        terminal_cand = {2*(s-1) // 2, 2*(s-1) // 2 + s % 2 - 1}
        for j in rmi_ws:
            if (j, 0) in terminal_cand:
                continue
            if j > rmi_ws[-1][1]:
                cands = defaultdict(int)
                for rki in kpi_ws[j-1]:
                    cands[kki + rki + rki[j-1]] += segtree.query(*rki)
                for rk, tmp in cands.items():
                    if tmp > 0:
                        ans_queries[tmp] += 1
        ans_query = sum(ans_queries.values())
        print(ans_query)

