            max_val = max(max(f(a, b - k) for a in range(k, n - k + 1)), max(f(a - k, b) for a in range(k, n - k + 1)), max(f(a, b + k) for a in range(k, n - k + 1)))

            # check individual rows and columns
            for a in range(k, n - k + 1):
                if f(a, b) == max_val:
                    return a, b
            for a in range(k, n - k + 1):
                for c in range(k, m - k + 1):
                    if f(a, c) == max_val:
                        return a, c

        # if we can't find a solution that satisfies the outer bounds, return None, None
        return None, None

def f(a, b):
    return min([b // x for x in range(1, a + 1)] + [y % a for y in range(x + 1, b + 1)])
