from functools import lru_cache

def count_palindromes(s, n):
    s = list(s)
    @lru_cache(maxsize=None)
    def helper(index, is_odd):
        if index == len(s): 
            return is_odd 
        # Odd length palindrome
        if is_odd:
            if s[index] == s[index ^ 1]:
                return helper(index + 1, False) 
            else:
                return 0 
        else:
            insert_after_odd = false
            insert_after_even = false
            for j in range(len(s)):
                if index == j:
                    continue 
                if s[index] == s[j] and not insert_after_odd:
                    insert_after_odd = is_odd 
                    insert_after_even = False
                elif s[index] == s[j]:
                    insert_after_odd = False
                    insert_after_even = True
                else:
                    break 
            if insert_after_odd or insert_after_even:
                return helper(index + 2, insert_after_odd)
            else:
                return helper(index + 1, is_odd)
    return helper(0, True) % 10007

