def evaluate_formula(formula):
    stack = []
    for char in formula:
        if char == '0' or char == '1':
            stack.append(int(char))
        elif char == '(':
            stack.append('(')
        elif char == ')':
            while stack[-1] != '(':
                if stack[-1] == '0':
                    stack[-1] = '0'
                elif stack[-1] == '1':
                    stack[-1] = '1'
            stack.pop()
        elif char == '?' or char == '|':
            stack.append('AND')
        elif char == '&':
            stack.append('OR')
        elif char == '^':
            stack.append('XOR')
    return stack.pop()

