def sieve_of_eratosthenes(n):
    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, n + 1) if is_prime[p]]

def solve(chessboard_size, deletions):
    n = chessboard_size
    primes = sieve_of_eratosthenes(n + 1)
    max_rooks = n

    for p in primes:
        if p == 2 or (n % p == 0):
            continue
        max_rooks *= (2 * p + 1)
        delete_cells = {}
        for x1, y1, x2, y2 in deletions:
            for x in range(x1, x2 + 1):
                try:
                    del delete_cells[(x, y1)]
                except KeyError:
                    pass
                try:
                    del delete_cells[(x, y2)]
                except KeyError:
                    pass
        if delete_cells:
            max_rooks //= len(delete_cells)
    return max_rooks

