import sys

def find_span_tree(n, graph, k):
    icit_group = [-1] * (n + 1)
    stack = []
    icit_level = [[] for _ in range(n + 1)]
    icit_level[1] = []
    icit_group[1] = 1

    def find(x):
        if icit_group[x] < 0:
            return x
        else:
            icit_group[x] = find(icit_group[x])
            return icit_group[x]

    def union(x, y):
        p = find(x)
        q = find(y)
        if p != q:
            if icit_level[p] < icit_level[q]:
                icit_level[p] += icit_level[q]
                icit_group[q] = p
            else:
                icit_level[q] += icit_level[p]
                icit_group[p] = q
            icit_group[p] = icit_group[q] = -1

    def kruskal():
        mst = []
        while stack:
            u, v, w = stack.pop()
            if find(u) != find(v):
                mst.append((w, (u, v)))
                union(u, v)
        if len(mst) == 2 * k - 1:
            return mst
        return []

    stack.append(list(graph.items())[0])
    while stack:
        u, v, w = stack.pop()
        if find(u) == find(v):
            icit_level[u] += icit_level[v] + w
        else:
            mst = kruskal()
            if not mst:
                return [-1]
            mst[0], mst[-1] = 0, len(mst) - 1
            stack.append((u, stack[-1][1], 0))
            stack.append((v, stack[-1][1], len(mst) - 1))
            for i in range(0, len(mst) - 1, 2):
                node1 = find(mst[i])
                node2 = find(mst[i + 1])
                if node1 == node2:
                    continue
                if icit_level[node1] < icit_level[node2]:
                    icit_level[node2] = icit_level[node1]
                    icit_group[node2] = node1
                else:
                    icit_level[node1] = icit_level[node2]
                    icit_group[node1] = node2
        else:
            i = [j for k, j in enumerate(mst) if i[k] == find(u)]
            if i:
                u, v = mst[i[0]]
            if k:
                v = mst[-2]
            mst.append((w, (u, v)))
            w -= icit_level[u] + icit_level[v] + w
            union(u, v)
    return mst

def main():
