            continue
        elif defaultdict.get((i + 1), -1) == -1:
            stop = i + 1
            while stop >= 0 and stop >= halt_index:
                stop = defaultdict.get((stop - 1), stop - 1) or halt_index
                if defaultdict.get((stop + 1), stop + 1) != stop:
                    break
                stop -= 1
            substring = [i+1 for i in range(i, stop+1)]
            state = stop + 1
        elif state == 1:
            index = i
        elif state == 0 and i >= 1 and (i-1) > halt_index and i == halt_index:
            continue
        elif i == i + halt_index and state == -1 and i > 0:
            state = 2
    return index, state, defaultdict

def select_k(max_overall, overall, n, dict, halt_index):
    current = max_overall
    current_total = overall
    for i in range(n):
        if i < n-1:    
            if i > halt_index:
