                            if state == -1:
                                current = max(current, current_total)
                                current_total = int(indices[i])
                                dict[(halt_index, i)] = halt_index
                                break
                            halt_index = max(indices[i], halt_index)
                            indices = [i, halt_index]
                            i = indices[1] - 1
                            break
                    current_total = max(dict.get((j, j+1), j+1))+1
                current, remaining = max(current, current_total), 0
                for j in range(i+1, n):
                    if dict.get((i, j), j+1) != -1:
                        break
                if i > 0:
                    for j in range(i-1, -1, -1):
                        if i < n-1:
                            if dict.get((i-1, j), j+1) != -1 and j > 0 and i >= j+1:
                                indices, state, current_index = find_increasing_stack(dict, n, halt_index)
                                if i == halt_index:
                                    current = max(current, current_total)
                                    current_total = max(indices[i], dict[(halt_index if halt_index == i+1 else i, j)])
                                    dict[(halt_index if halt_index == i+1 else i, j)] = halt_index
                                break
                        dict[(j, j+1)] = j+1
                        remaining += 1
            else:
                if i == halt_index:
                    indices, state, current_index = find_increasing_stack(dict, n, halt_index)
                    if state == -1:
                        current = max(current, current_total)
                        current_total = int(indices[i])
                        dict[(halt_index, i)] = halt_index
                        break
                    halt_index = max(indices[i], halt_index)
