                    i = i - 1
                current_total = max(dict.get((i, i+1), i+1)) + defaultdict.get((i, max(i, halt_index)+1), max(i, halt_index)+1)
        else:
            current, current_total = max(overall, current_total), max(overall, current_total)
    return current_total if current <= n else max_overall - remaining

