import sys

# Convert the formula to a complex logic formula
def parse_formula(formula):
    stack = []
    i = 0
    while i < len(formula) or stack:
        if formula[i] == '(':
            j = i
            while j < len(formula) and formula[j] != ')':
                j += 1
            j += 1
            formula = formula[:j-1] + parse_formula(formula[j:])
            i = j + 1
        elif formula[i] == '?':
            stack.append(formula.count('?'))
        elif formula[i].isalpha():
            formula = formula[i:].lstrip('01')
            if not formula:
                i += 1
                continue
            if formula[0] not in '01':
                formula, balanced = solve(formula[1:-1], balanced=True)
                formula = formula[:1] + formula
        else:
            i += 1
    return ''.join(formula.split()), stack

def solve(formula, balanced=False):
    if balanced and '(&|)' * 4 in formula:
        return '0', True
    for length in range(1, len(formula)+1):
        for left in range(len(formula)):
            for right in range(left + length, len(formula)+1):
                prefix = formula[:left]
                middle = ' & '.join(formula[left:right]).replace('1', '0').replace('0', '1').replace('?', '-')
                for char in '01?^':
                    result = '1' if (prefix == '0' and char == '1') or (prefix == '1' and char == '0') or (balanced and (not middle or '||||' in '('+middle+').') else '0'
                    if middle and char != prefix[-1] and len(''.join(map(lambda x: x[:-1], middle.split(char)))) > len(prefix[:-1]):
                        continue
                    new_form = prefix + result + formula[right:]
                    c = parse_formula(new_form)[1]
                    if result == '1' or (c and (not ok(formula, new_form)) and (not ok(formula) or not ok(formula[formula.index(new_form)-len(formula)+1:]))):
                        return new_form, False
    return '0', True

def ok(formula, result):
    return bool('*'? if formula[0] == '0' else 0 < len(result) < 3+len(formula[1:])) and all(formula[i] == '0' or 1 & 1 for i in range(1, len(result)+1)) or formula[0] == '1'
