from collections import defaultdict

def find_dp_k_tree(n, edges, k):
    tree = [[] for _ in range(n+1)]
    parent = [-1] * (n+1)
    dp = [-1] * (n+1)
    out = [0] * (n+1)

    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
        out[u] += 1
        out[v] += 1

    def subtree_count(node):
        if out[node] < k:
            return 1
        count = 1
        for child in tree[node]:
            count += subtree_count(child)
        return count

    def dfs(node, depth):
        max_depth = max(dp[node], depth-1)
        for child in tree[node]:
            if dp[child] == -1:
                dp[child] = dfs(child, max_depth+1)
        return max_depth

    for u in range(1, n+1):
        if out[u] >= k:
            dp[u] = dfs(u, 2)
        else:
            dp[u] = 1

    return sum(dp), sum(dp*x for x in out)


