from heapq import *
from math import gcd

def find_gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def count_packets(n, m, s, t, prefix):
    if not t:
        return 0
    n1, n2, n3 = n // t
    m1, m2, m3 = m // t
    s1, s2, s3 = s // t

    lcm_n = n1 * n2 * n3
    lcm_m = m1 * m2 * m3
    lcm_s = s1 * s2 * s3

    factorial_n = 1
    for i in range(1, n + 1):
        factor = find_gcd(n1 // factorial_n, i) * gcd(m1 // factorial_n, i)
        factor *= ((n1 // i) + (m1 // i)) - 1
        if factor:
            factorial_n *= i * factor
    factorials_m = 1
    for i in range(1, m + 1):
        factor = find_gcd(m1 // factorials_m, i) * gcd(n1 // factorials_m, i)
        factor *= ((m1 // i) + (n1 // i)) - 1
        if factor:
            factorials_m *= i * factor

    factorials_s = 1
    for i in range(1, s + 1):
        factor = find_gcd(s1 // factorials_s, i) * gcd(m1 // factorials_s, i) * gcd(n1 // factorials_s, i)
        factor *= ((s1 // i) + (m1 // i) + (n1 // i)) - 1
        if factor:
            factorials_s *= i * factor

    total = 0
    for i in range(n1, n2 + 1):
        factor1 = find_gcd(n1 // i, m1 // lcm_n) * gcd(m1 // i, n1 // lcm_m)
        factor1 *= ((m1 // i) + (n1 // i)) - 1
        for j in range(m1, m3 + 1):
            factor2 = find_gcd(m1 // j, n3 // lcm_s) * gcd(n3 // j, m3 // lcm_s)
            factor2 *= ((n3 // j) + (m3 // j)) - 1
            if factor1 and factor2:
                total += i * j * factorials_n // (factorials_m * factorials_s)

    return int(total / t)
