# that multiply to s. The program finds the prime factorization of the numbers
# and then finds the smallest set of factor pairs that multiply to s.
def smallest_factors(s, min_factor):
    factors = {}
    for i in range(min_factor, 10**6 + 1):
        while s % (i * i) == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            s //= i * i
    if s:
        factors[s] = 1
    return min(factors.values())

