def evaluate_formula(formula):
    tokens = formula.replace("(", "( ").replace(")", " )").split()
    stack = []
    for token in tokens:
        if token == '?':
            stack.append((1, 0, 1))
        elif token == '^':
            stack.append((1, 1, 1))
        elif token == '&':
            stack.append((1, int(stack.pop()[1] and stack.pop()[2]), 1))
        elif token == '|':
            stack.append((1, int(stack.pop()[1] or stack.pop()[2]), 1))
        else:
            if len(stack) < 2:
                return "NO"
            r1, n1, o1 = stack.pop()
            r2, n2, o2 = stack.pop()
            if token == '?' in (r1, r2):
                return "NO"
            if token == '?' and (r1, r2):
                if r2 == 1 and n2 > n1:
                    stack.append(((r1 and o1) or (n1 and o2)), n1 + (o1 or o2), o1 or o2)
                elif r1 == 1 and n1 > (n2 and o2):
                    stack.append(((r2 and o2) or (n2 and o1)), n2 + (o1 or o2), o1 or o2)
            else:
                stack.append((int(r1 | r2), max(n1, n2), max(o1, o2)))
    return "YES"

def mass_evaluations(requirements, evaluations):
    if len(requirements) <= 1:
        return evaluate_formula(requirements[0])
    for i in range(len(requirements) - 1):
        if mass_evaluations(requirements[:i + 1] + [OR(requirements[i + 1:])] + requirements[i + 1:], evaluations + 1):
            return "YES"
    return "NO"

def OR(seq):
    if len(seq) == 1:
        return seq[0]
    for i in range(1, len(seq)):
        result = seq[i]
        for j in range(i):
            if seq[j] and not(seq[j] and seq[i]):
                result = j
                break
        if result:
            break
    return seq[result]
