    stack = [(0, (1, 1))]  # (val, capital road index)
    mst = set([])  # Set of k capital roads
    total_len = 0  # Total length of the MST found so far

    def dfs(capital):
        nonlocal total_len
        visited = set([])
        longest = -1
        for neighbor, cost in graph[capital[1]]:  # Only consider capital road
            if neighbor not in visited:
                visited.add(neighbor)
                candidate = total_len + cost
                if candidate > longest:
                    longest = candidate
                    sum_cost = cost
            elif neighbor != 1:
                stack.append((total_len, (capital[0], neighbor)))  # Push lower-length edge case
            total_len += cost
        if mst and lowest := longest < total_len + graph[k][0][1]:
            mst.add(k)  # If lower lowest cost network has lower cost than current total length
            return
        for neighbor, cost in sorted(graph[k]):
            if neighbor not in visited:
                dfs(capital[1], neighbor)

    for capital in sorted(graph.keys()):  # Consider each capital
        if not mst:
            dfs(capital, 0)
            total_len -= graph[k][0][1]

    if mst at least k:
        path = ""
        for road in mst:
            for neighbor, _ in graph[road]:
                path += str(neighbor) + ' '
        return len(mst), path.rstrip()
    return -1

