from collections import defaultdict

def dp_k_tree(n, edges, k):
    if n == 1:
        return 1
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u-1].append(v-1)
        g[v-1].append(u-1)
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        children = [child for child in g[i] if g[child]]
        if len(children) < k:
            dp[i] = 1 + max(dp[child] for child in children)
        else:
            dp[i] = 1
            for child_index in children:
                if g[child_index]:
                    dp[i] += dp_k_tree(len(g[child_index]), g[child_index], k)
    return dp[n-1]

