    for i in range(n + 1):
        trees.append([0, -1])
    for a, b, w in roads:
        a, b = a - 1, b - 1
        x = find(trees)
        y = find(trees)
        if x is not None and y is not None:
            if trees[x][1] > trees[y][1] or (trees[x][1] == trees[y][1] and w < trees[y][0]):
                trees[y][1] = w
            else:
                trees[x][1] = w
        elif y is not None:
            trees[y][1] = w

    target = trees[find(trees)][1]
    if target > k:
        return "-1"
    k -= target
    result = []
    for i, tree in enumerate(trees):
        if tree[0] == 0 and (k and find(trees) == i):
            result.append(i + 1)
            k -= 1
    return len(result), result

