        good_subarrays = [True] * n
        missing = {num: freq[num] for num in freq if freq[num] == max_freq}

        # Check if any frequency is missing
        if not missing:
            continue

        for num in freq:
            if num in missing and missing[num] > 0:
                missing[num] -= 1

        # If no frequency is missing, all numbers occur max_freq times
        if all(not missing[num] for num in freq if num in missing):
