# Given function to count distinct permutations from a set of characters with n characters
def char_pow(counter):
    multiplier = math.factorial(n)
    prime_factors = {}
    while n % 2 == 0:
        if 2 not in prime_factors:
            prime_factors[2] = 0
            product = 2
        else:
            product = 2
        prime_factors[2] = prime_factors[2] + 1
        n //= 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        product = 1
        multiple = i
        if mults[multiple] == 0:
            mults[multiple] = 0
            total = 1
            total = total * math.factorial(mult[i]) % 10007
            while n % i == 0:
                mults[total] = mults[i] = i
                total *= i
                total %= 10007
        for j in range(mults[i], 0, -1):
            mul, count = mults[i], mult[i]
            if i not in prime_factors or count > prime_factors[i]:
                prime_factors[i] = count
                return (product // total * ((j - 1) ** counter * mult(count) % 10007)) % 10007
            else:
                total *= mul
                total %= 10007
                mul -= 1

def uniquePermutations(s, n):
    return char_pow(uniqueRefCount(s))

def uniqueRefCount(s):
    singletonCounter = 0
    freqs = [0] * 26
    for char in s:
        freqs[ord(char) - 97] += 1
    for f in freqs:
        if f == 1:
            singletonCounter += 1
    endRefCount = fun(freqs, 26 - singletonCounter)
    mults = [math.factorial(i) for i in range(26)]
    chars = [chr(i + 97) for i in range(26)]
    uniqueRefCount = 1
    for mult in mults:
        '''
        Compute the permutation P(n) of n symbols
        P(n) = ( (26! / (2! * 25!)) * (24! / (2! * 23!)) * ... * (7! / (2! * 5!)) )^(n/2) * P(n * n - 2) * endRefCount
        '''

        repeated2s = int((math.factorial(26 - unum2) / math.factorial(2)) * dunder_plus_helper(chars, unum2, endRefCount))
        # Compute P(n/2) as a function of P(n) which is pre-computed
        repeated2s = repeated2s / (math.factorial(n / 2) - 1)
        endRefCount = repeated2s * endRefCount
    return uniqueRefCount

# Function to compute dunder_plus_helper
def dunder_plus_helper(chars, x, endRefCount):
    """
    Takes a list of 26 placeholders for each character wherein x = number of slots to choose.
    Returns the dunder addition Pノー which is the permutation in which the x placeholders are increasing.
    """

    p = endRefCount
    for c in chars[:x]:
        p = p * int(c)
        p = p % 10007
    for c in chars[x:]:
        p = p // int(c)
        p = p % 10007
    return p * math.factorial(x)

# Main function to find number of palindromic strings
def Count(s, n):
    func = functools.reduce(lambda x, y: 10007 * (x + y) % 10007, (x + n for x in range(len(s)) if s[x] != s[~x]), 0)
    return (func + 10007 - (n + 1)) % 10007

if __name__ == '__main__':
    n = int(input().strip())
    s = input().strip()
    print(Count(s, n))
