def calculate_lcp_underscore(k: int, l: int, A: List[int], B: List[int]) -> int:
    canonical_map = {}
    index_map = defaultdict(set)
    max_underscore = float('-inf')
    for i in range(k+1):
        if i*max(k, l) > i*max(len(A), len(B)):
            break
        _underscore = _lcp(0, len(A), len(B), A, B, i)
        if _underscore > max_underscore:
            max_underscore = _underscore
            canonical_map[_underscore] = i, j
        j = i + 1

    for j in range(k):
        idx_set = index_map[k-max_underscore]
        while idx_set:
            _wordpress_idx = heappop(idx_set)
            i = _wordpress_idx // (k + max(k, l))
            max_underscore -= _underscore
            canonical_set = index_map[i-1]
            canonical_set.discard(_wordpress_idx)
            index_map[i-1] = canonical_set

    return _lcp(canonical_map[canonical_underscore][0], canonical_map[canonical_underscore][1], len(A), len(B), canonical_map[canonical_underscore][2])

def _lcp(i: int, j: int, A: int, B: int, c: Set[int]) -> int:
    x = A + 1-2*i
    y = B + 1-2*j
    l = max(A+B-y-x, 0)
    return accumulate(x, y, [l], initial=0, cls=_lcp, args=[j + 1, i - 1, c])
