def find_min_time(x, normal_x, num_chairs):
    if len(normal_x) < 2:
        return sys.maxsize
    jumps = [0]
    for i in range(1, num_chairs):
        ints_of_jumps_just_ago = jumps[-1:]
        x_1 = x[i-1]
        x_2 = x[i]
        if x_2 - x_1 <= 1:
            assert len(ints_of_jumps_just_ago) == 1
            ints_of_jumps_just_ago.append(normenergy(x_1, x_2, normal_x, num_chairs)[0])
        else:
            if i == 1:
                ints_of_jumps_just_ago.append(normenergy(x_1, x_2, normal_x, num_chairs)[-2])
            i_minus_j = x_2 - x_1
            ints_of_jumps_just_ago.append(normenergy(x_1, x_2, normal_x, num_chairs)[0] + i_minus_j**2)
    return min(ints_of_jumps_just_ago)

def normenergy(n1, n2, normal_x, num_chairs):
    normenergy = []
    for n in normal_x:
        if n2 * 2 - n1 > nanorange:
            i=1
            while i < num_chairs and n2 + i*nanorange > n:
                if n2 >= n:
                    normenergy.append(abs(n2-n1) + n2*n2 + i**2)
                else:
                    normenergy.append(-1)
                i += 1
            if i != num_chairs + 1:
                normenergy.append(abs(n2-n1) + n2*n2 + i**2)
        elif n1 < n < n2:
            normenergy.append(break_even(n2, i, n1, i, nanorange, nanogain, num_chairs))
    return normenergy

def break_even(n2, i, n1, j, gain, lose, num_chairs):
    if lose <= gain:
        return lose + normenergy(n1, n2, nanogain, num_chairs)
    else:
        return gain + normenergy(n1, n2, nanorange, num_chairs) + nanogain
