def longest_common_prefix(s: str) -> int:
    def check(l):
        i = 0
        for i in range(len(l)):
            if s[0:i+1] != s[i]:
                return i-1
        return len(s)

    prefix = ''
    for cand in s[:-1]:
        i = check(cand)
        if not i:
            break
        prefix += cand[:i]
    return prefix

def lcp_calc(s: str, a: List[int], b: List[int]) -> int:
    query_lcp = 0
    a_set, b_set = set(a), set(b)
    for lcp_s in s[:len(a)]:
        if lcp_s in a_set and lcp_s in b_set:
            query_lcp += 1
    subst_s = s[len(a):]
    for lcp_s in subst_s:
        if lcp_s in a_set and lcp_s in b_set:
            query_lcp += 1
    return query_lcp


