import sys

def dfs(k, depth, children_ready, node, visited, tree):
    if depth > tree[node]:
        return depth
    if visited[node]:
        return 0
    visited[node] = True
    additional_depth = 0
    for child in tree[node]:
        if not visited[child]:
            additional_depth = max(additional_depth, dfs(k, depth + 1, min(depth + 1, children_ready[child]), child, visited, tree))
    return depth + additional_depth

def solve(n, tree, root):
    dp = [0] * (n + 1)
    visited = [False] * (n + 1)
    visited[root] = True
    tree = [set() for _ in range(n)]
    for u, v in tree[root]:
        tree[u].add(v)
        tree[v].add(u)
    for i in range(root, n):
        for child in tree[i]:
            if not visited[child]:
                visited[i] = True
                break
    max_depth = int(len(tree) / k)
    root_depth = dfs(k, 1, k, root, visited, tree)
    if root_depth < max_depth:
        max_depth = root_depth
    return sum(dp[:root]) + max_depth

